import math
# Limiting QDA example: independent mean signal X and variance signal Y.
# Class 1: X~N(1,1), Y~N(0,1); class 2: X~N(2,1), Y~N(0,4).
def phi(z):
    return math.exp(-z*z/2)/math.sqrt(2*math.pi)
def cdf(z):
    return 0.5*math.erfc(-z/math.sqrt(2))
def integrand(z):
    threshold_1=1.5+math.log(2)-3*z*z/8
    threshold_2=1.5+math.log(2)-3*(2*z)**2/8
    return 0.5*phi(z)*(cdf(1-threshold_1)+cdf(threshold_2-2))
steps=20000
lo,hi=-10,10
width=(hi-lo)/steps
value=integrand(lo)+integrand(hi)
for i in range(1,steps):
    value+=(4 if i%2 else 2)*integrand(lo+i*width)
print(f'Oracle projected rule error: {cdf(-0.5):.8f}')
print(f'Full Bayes rule limiting error: {value*width/3:.8f}')
print('This is an independent check of a counterexample, not a replication of the manuscript experiments.')
